package com.classeschedule.widget;
import android.app.PendingIntent;import android.appwidget.AppWidgetManager;import android.appwidget.AppWidgetProvider;import android.content.*;import android.widget.RemoteViews;
public class ScheduleWidgetProvider extends AppWidgetProvider{public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,m,id);}public void onReceive(Context c,Intent i){super.onReceive(c,i);AppWidgetManager m=AppWidgetManager.getInstance(c);for(int id:m.getAppWidgetIds(new ComponentName(c,ScheduleWidgetProvider.class)))update(c,m,id);}static void update(Context c,AppWidgetManager m,int id){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget);SharedPreferences p=c.getSharedPreferences("schedule",Context.MODE_PRIVATE);v.setTextViewText(R.id.widget_subject,p.getString("subject","No class scheduled"));v.setTextViewText(R.id.widget_time,p.getString("time","—"));v.setTextViewText(R.id.widget_room,p.getString("room","Room —"));v.setTextViewText(R.id.widget_teacher,p.getString("teacher","Teacher —"));Intent o=new Intent(c,MainActivity.class);v.setOnClickPendingIntent(R.id.widget_subject,PendingIntent.getActivity(c,0,o,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT));m.updateAppWidget(id,v);}}